<?php require_once __DIR__.'/../api/auth.php'; if (!empty($_SESSION['admin_id'])) { header('Location: dashboard.php'); exit; } $error=''; if ($_SERVER['REQUEST_METHOD']==='POST') { $s=db()->prepare('SELECT * FROM admins WHERE email=?'); $s->execute([strtolower(trim($_POST['email']??''))]); $a=$s->fetch(PDO::FETCH_ASSOC); if ($a && password_verify($_POST['password']??'', $a['password_hash'])) { session_regenerate_id(true); $_SESSION['admin_id']=$a['id']; header('Location: dashboard.php'); exit; } $error='Credenciais inválidas.'; } ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/css/admin.css"><title>Admin Hotspot</title></head><body><form class="login" method="post"><h1>Administração</h1><?php if($error):?><p class="error"><?=htmlspecialchars($error)?></p><?php endif?><label>E-mail<input name="email" type="email" required></label><label>Senha<input name="password" type="password" required></label><button>Entrar</button></form></body></html>
